---@module "overseer"
---@module "dap"

---@class OverseerOptions: overseer.TaskDefinition
---@field cwd? string Working directory to run `run_main` in
---@field env? table<string, string> Additional environment variables
---@field strategy? overseer.Serialized Definition for a run Strategy
---@field metadata? table<string, any> Arbitrary metadata for your own use
---@field default_component_params? table<string, any> Default values for component params
---@field ephemeral? boolean Indicates that this task was generated by another task (e.g. with run_after)
---@field components? overseer.Serialized[] List of components to attach. Defaults to `{"default"}`

--- See available gdb options at: https://sourceware.org/gdb/current/onlinedocs/gdb.html/Debugger-Adapter-Protocol.html
---@class DapOptions: dap.Configuration
---@field type string
---@field request? "launch"|"attach"
---@field name? string Can be used to overwrite the name set in Task
---@field [string] any

---@class TaskContext
---@field main_name? string Defines the name used by the task generated by `run_main`. The task's name is used if not defined
---@field is_overseer? true
---@field is_dap? true
---@field failed? true Can be set by any of the run function to indicate that they failed
---@field main_run_overseer? overseer.Task The completed main task, available to `run_post`
---@field [string] any

---@class Task
---@field name string Name of the task
---@field enabled? boolean
---@field first_run_pre? fun(context: table): overseer.Task[]|nil Executed the first time this task is ran and never on `run_last_*_task`. Usually used to ask the user for input
---@field run_pre? fun(context: table): overseer.Task[]|nil Always executed before `run_main`
---@field run_main fun(context: table): string[]|string Returns the command to run. For DAP, this must be a list with the executable first.
---@field run_post? fun(context: table): overseer.Task[]|nil Always executed after `run_main`
---@field overseer? { enabled: boolean, options?: OverseerOptions } 'options' is used by all cmds
---@field dap? { enabled: true, options: DapOptions } | { enabled: false, options?: DapOptions }

local M = {
	enabled = true,
	overseer = {
		enabled = true,
		options = {
			ephemeral = true,
		},
	},
	dap = {
		options = {
			request = "launch",
			cwd = "${workspaceFolder}",
		},
	},
}

return M
